FUNCTION_BLOCK FB
VAR_INPUT
    flowLow : BOOL;
    ackBtn : BOOL;
    sensorOK : BOOL;
END_VAR
VAR_OUTPUT
    alarmActive : BOOL;
    alarmAcked : BOOL;
    highHigh : BOOL;
END_VAR
VAR
    prev_flowLow : BOOL := FALSE;
    prev_ackBtn : BOOL := FALSE;
END_VAR

// 高优先级报警
highHigh := NOT sensorOK;

// 计算上升沿
VAR temp_rising : BOOL;
temp_rising := ackBtn AND NOT prev_ackBtn;

// 低优先级报警逻辑
// 计算新的 alarmActive 和 alarmAcked

IF NOT alarmActive THEN
    IF flowLow THEN
        alarmActive := TRUE;
        alarmAcked := FALSE;
    ELSE
        alarmActive := FALSE;
        alarmAcked := FALSE;
    END_IF
ELSE
    // 当前 alarmActive 为 TRUE
    // 根据逻辑：alarmActive 保持 TRUE，除非确认沿且条件消失
    IF temp_rising AND NOT flowLow THEN
        alarmActive := FALSE;
        alarmAcked := FALSE;
    ELSE
        alarmActive := TRUE;
        // 计算 alarmAcked
        IF temp_rising THEN
            // 确认沿，且条件存在或消失？
            IF flowLow THEN
                alarmAcked := TRUE;
            ELSE
                alarmAcked := FALSE; // 这种情况已经在上面清除了？但上面 if temp_rising and not flowLow then 清除，所以不会走到 else。
                // 实际上，如果 temp_rising and not flowLow，则上面已经清除，alarmAcked 设为 FALSE。
                // 所以这里 temp_rising and flowLow 的情况：alarmAcked := TRUE。
                alarmAcked := TRUE; // 因为 flowLow 为真，所以确认后已确认。
            END_IF
        ELSE
            // 无确认沿
            IF NOT flowLow THEN
                alarmAcked := TRUE; // 条件消失，自动置已确认
            ELSE
                alarmAcked := alarmAcked; // 保持不变
            END_IF
        END_IF
    END_IF
END_IF

